<script setup lang="ts">
import { computed, ref, shallowRef } from 'vue'
import DialogFrame from '../../ui/DialogFrame.vue'
import TableIcon from '../../components/TableIcon.vue'
import type { Appearance } from '../presentation/model'
import { buildExportBook, downloadExport, exportCSV, exportFields, normalizeExportOptions, readExportPresets, saveExportPreset, type ExportBook, type ExportField, type ExportGroup, type ExportPreset } from './model'

const props=withDefaults(defineProps<{title?:string;filename?:string;fields:readonly ExportField[];groups:readonly ExportGroup[];initialScope?:string;presets?:unknown;savePresets?:(presets:ExportPreset[])=>void|Promise<void>;conditions?:readonly string[];appearance?:Partial<Appearance>;rawValueLabel?:string;footerNote?:string}>(),{title:'导出数据',filename:'数据列表',rawValueLabel:'原值',footerNote:'模板下载使用固定字段，不受这里影响。'})
const emit=defineEmits<{close:[];complete:[count:number,format:'xlsx'|'csv']}>()
const fields=computed(()=>exportFields(props.fields)),options=ref(normalizeExportOptions({},fields.value)),scope=ref(props.initialScope??props.groups[0]?.id??'')
const order=ref(fields.value.map(field=>field.id)),saved=shallowRef<ExportPreset[]>([]),selectedPreset=ref(''),name=ref(''),busy=ref(false),error=ref(''),status=ref(''),dragged=ref('')
const preview=shallowRef<ExportBook>(),confirmation=ref<'replace'|'delete'>()
try{saved.value=readExportPresets(props.presets,fields.value)}catch{error.value='导出方案读取失败，请重新保存方案。'}
const group=computed(()=>props.groups.find(item=>item.id===scope.value))
const ordered=computed(()=>order.value.flatMap(id=>{const field=fields.value.find(item=>item.id===id);return field?[field]:[]}))
const visibleKeys=computed(()=>[...new Set(fields.value.filter(field=>field.column.visible!==false).flatMap(field=>{
  const secondary=field.column.content?.showSecondary&&fields.value.find(item=>item.column.field===field.column.content?.secondaryField)
  return secondary?[field.id,secondary.id]:[field.id]
}))])
const visibleOnly=computed(()=>options.value.keys.length===visibleKeys.value.length&&options.value.keys.every(key=>visibleKeys.value.includes(key)))
const hasTotal=computed(()=>fields.value.some(field=>field.total&&options.value.keys.includes(field.id)))
function selectPreset(){const preset=saved.value.find(item=>item.id===selectedPreset.value);if(!preset)return;options.value=normalizeExportOptions(preset.options,fields.value);order.value=[...options.value.keys,...fields.value.map(field=>field.id).filter(id=>!options.value.keys.includes(id))];name.value=preset.name;error.value=''}
function toggleField(id:string,event:Event){const selected=new Set(options.value.keys);(event.target as HTMLInputElement).checked?selected.add(id):selected.delete(id);options.value.keys=order.value.filter(key=>selected.has(key))}
function toggleVisible(event:Event){options.value.keys=(event.target as HTMLInputElement).checked?[...visibleKeys.value]:[...order.value];order.value=[...options.value.keys,...order.value.filter(key=>!options.value.keys.includes(key))]}
function move(id:string,target:number){const from=order.value.indexOf(id);if(from<0||target<0||target>=order.value.length)return;const next=[...order.value];next.splice(from,1);next.splice(target,0,id);order.value=next;options.value.keys=next.filter(key=>options.value.keys.includes(key))}
function drop(id:string){move(dragged.value,order.value.indexOf(id));dragged.value=''}
async function commitPreset(replace=false){if(busy.value)return;error.value='';try{const next=saveExportPreset(saved.value,name.value,options.value,fields.value,replace);busy.value=true;await props.savePresets?.(next);saved.value=next;selectedPreset.value=next.find(item=>item.name===name.value.trim())?.id??'';status.value='导出方案已保存。';confirmation.value=undefined}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败，请重试。'}finally{busy.value=false}}
function requestSave(){const key=name.value.trim().normalize('NFKC').toLocaleLowerCase();if(saved.value.some(item=>item.name.normalize('NFKC').toLocaleLowerCase()===key)){confirmation.value='replace';return}void commitPreset()}
async function deletePreset(){if(busy.value)return;error.value='';busy.value=true;try{const next=saved.value.filter(item=>item.id!==selectedPreset.value);await props.savePresets?.(next);saved.value=next;selectedPreset.value='';confirmation.value=undefined;status.value='方案已删除。'}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败，请重试。'}finally{busy.value=false}}
function showPreview(){try{preview.value=buildExportBook((group.value?.rows??[]).slice(0,10),fields.value,{...options.value,total:false,metadata:false},{scope:group.value?.label??'',appearance:props.appearance})}catch(cause){error.value=cause instanceof Error?cause.message:'预览失败。'}}
async function exportData(){if(busy.value)return;error.value='';if(!group.value?.rows.length){error.value='没有可导出的记录。';return}busy.value=true;try{const book=buildExportBook(group.value.rows,fields.value,options.value,{scope:group.value.label,conditions:props.conditions,appearance:props.appearance}),format=options.value.format,date=new Date(),suffix=`${date.getFullYear()}${String(date.getMonth()+1).padStart(2,'0')}${String(date.getDate()).padStart(2,'0')}`;if(format==='xlsx'){const {writeXlsx,xlsxMime}=await import('./xlsx');downloadExport(writeXlsx(book),`${props.filename}_${group.value.label}_${suffix}.xlsx`,xlsxMime)}else downloadExport(exportCSV(book),`${props.filename}_${group.value.label}_${suffix}.csv`,'text/csv;charset=utf-8');emit('complete',group.value.rows.length,format);emit('close')}catch(cause){error.value=cause instanceof Error?cause.message:'生成失败，请重试。'}finally{busy.value=false}}
const previewValue=(value:unknown)=>value instanceof Date?value.toISOString().slice(0,10):String(value??'')
</script>
<template>
  <DialogFrame class="bt-export-dialog" :title="title" subtitle="使用已应用的查询结果。文件在本地生成，不上传数据。" :busy="busy" :aria-busy="busy" @close="emit('close')">
    <fieldset :disabled="busy" class="bt-export-controls">
      <div class="bt-export-presets"><label class="bt-ui-field"><span>导出方案</span><select v-model="selectedPreset" aria-label="已保存的导出方案" @change="selectPreset"><option value="">不使用方案</option><option v-for="preset in saved" :key="preset.id" :value="preset.id">{{preset.name}}</option></select></label><button class="bt-ui-icon" aria-label="删除导出方案" :disabled="!selectedPreset" @click="confirmation='delete'"><TableIcon name="trash"/></button></div>
      <div class="bt-export-layout"><aside class="bt-export-sidebar"><h3>导出范围</h3><div class="bt-export-ranges"><label v-for="item in groups" :key="item.id"><input v-model="scope" type="radio" name="bt-export-scope" :value="item.id" :disabled="!item.rows.length"/>{{item.label}}（{{item.rows.length}} 条）</label></div>
        <label class="bt-ui-field"><span>文件格式</span><select v-model="options.format"><option value="xlsx">Excel (.xlsx)</option><option value="csv">CSV (.csv)</option></select></label><label class="bt-ui-field"><span>导出值</span><select v-model="options.valueMode"><option value="display">显示值（包含映射和数字格式）</option><option value="raw">{{rawValueLabel}}</option><option value="both">显示值与原值分别输出</option></select></label>
        <label class="bt-ui-check"><input v-model="options.aliases" type="checkbox"/>使用自定义列名</label><label class="bt-ui-check"><input type="checkbox" :checked="options.style==='current'" :disabled="options.format==='csv'" @change="options.style=($event.target as HTMLInputElement).checked?'current':'standard'"/>应用当前文字样式</label><label class="bt-ui-check"><input v-model="options.total" type="checkbox" :disabled="!hasTotal"/>附加金额合计</label><label class="bt-ui-check"><input v-model="options.metadata" type="checkbox"/>附加查询条件和导出时间</label><p class="bt-ui-note">{{options.format==='csv'?'CSV 不保留样式；附加说明放在数据末尾。编号前导零请在表格软件中按文本导入。':'Excel 保留金额数值和日期类型；附加说明放在单独的工作表。'}}</p>
      </aside><section class="bt-export-fields"><div class="bt-export-heading"><h3>导出字段（{{options.keys.length}}）</h3><button class="bt-ui-button text" @click="options.keys=[...order]">全部字段</button></div><label class="bt-ui-check"><input type="checkbox" :checked="visibleOnly" @change="toggleVisible"/>仅导出当前显示的列</label><div class="bt-export-field-list"><div v-for="(field,index) in ordered" :key="field.id" class="bt-export-field" @dragover.prevent @drop.prevent="drop(field.id)"><button class="bt-ui-icon" :aria-label="`拖动${field.label}导出顺序`" draggable="true" @dragstart="dragged=field.id"><TableIcon name="grip" :size="13"/></button><label><input type="checkbox" :checked="options.keys.includes(field.id)" :aria-label="`导出${field.label}`" @change="toggleField(field.id,$event)"/><span>{{options.aliases?field.column.title:field.label}}</span></label><div><button class="bt-ui-icon" :aria-label="`上移导出字段${field.label}`" :disabled="index===0" @click="move(field.id,index-1)"><TableIcon name="chevron-up" :size="13"/></button><button class="bt-ui-icon" :aria-label="`下移导出字段${field.label}`" :disabled="index===ordered.length-1" @click="move(field.id,index+1)"><TableIcon name="chevron-down" :size="13"/></button></div></div></div><p class="bt-ui-note">拖动或用上下按钮调整导出顺序。操作按钮和选择框不会导出。</p></section></div>
      <p v-if="error" class="bt-ui-error" role="alert">{{error}}</p><p v-if="status" class="bt-export-status" role="status">{{status}}</p><div class="bt-export-save"><input v-model="name" maxlength="30" placeholder="方案名称，例如：财务核对" aria-label="导出方案名称"/><button class="bt-ui-button" @click="requestSave">保存方案</button></div>
    </fieldset>
    <template #footer><button class="bt-ui-button" :disabled="busy" @click="showPreview">预览</button><span class="bt-export-footer-note">{{footerNote}}</span><button class="bt-ui-button" :disabled="busy" @click="emit('close')">取消</button><button class="bt-ui-button primary" :disabled="busy||!options.keys.length||!group?.rows.length" @click="exportData">{{busy?'正在生成…':`导出 ${options.format==='xlsx'?'Excel':'CSV'}`}}</button></template>
  </DialogFrame>
  <DialogFrame v-if="preview" class="bt-export-preview" title="导出预览" :subtitle="`范围 ${group?.rows.length??0} 条；下方最多显示前 10 条，不含合计。`" @close="preview=undefined"><p class="bt-ui-note">数值展示为将写入文件的底层值；百分比等显示格式由 Excel 应用。</p><table><tbody><tr v-for="(row,index) in preview.sheets[0]?.rows" :key="index"><component :is="index?'td':'th'" v-for="(cell,column) in row" :key="column">{{previewValue(cell.value)}}</component></tr></tbody></table><template #footer><button class="bt-ui-button" @click="preview=undefined">关闭</button></template></DialogFrame>
  <DialogFrame v-if="confirmation" class="bt-export-confirm" :title="confirmation==='replace'?'更新导出方案':'删除导出方案'" :busy="busy" @close="confirmation=undefined"><p class="bt-ui-note">{{confirmation==='replace'?`使用当前字段和格式更新“${name.trim()}”？`:`确认删除“${saved.find(item=>item.id===selectedPreset)?.name}”？不删除任何数据。`}}</p><p v-if="error" role="alert" class="bt-ui-error">{{error}}</p><template #footer><button class="bt-ui-button" :disabled="busy" @click="confirmation=undefined">取消</button><button class="bt-ui-button" :class="confirmation==='delete'?'danger':'primary'" :disabled="busy" @click="confirmation==='replace'?commitPreset(true):deletePreset()">{{confirmation==='replace'?'更新方案':'删除方案'}}</button></template></DialogFrame>
</template>
<style>
.bt-export-dialog{line-height:normal;max-height:calc(100dvh - 50px);width:min(850px,calc(100vw - 28px))}.bt-export-controls{padding:0;margin:0;border:0;min-width:0}.bt-export-presets{display:flex;align-items:flex-end;gap:6px;margin-bottom:18px}.bt-export-presets .bt-ui-field{flex:1}.bt-export-presets>.bt-ui-icon{height:34px}.bt-export-layout{display:grid;grid-template-columns:255px minmax(0,1fr);gap:25px}.bt-export-layout h3{font-size:13px;margin:0 0 12px;color:#526177;font-weight:600}.bt-export-sidebar{border-right:1px solid #e8edf5;padding-right:22px}.bt-export-ranges{display:flex;flex-direction:column;gap:11px;margin-bottom:16px}.bt-export-ranges>label{display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid #e4eaf3;border-radius:6px;font-size:12px;cursor:pointer}.bt-export-ranges>label:has(input:checked){border-color:#91b8f6;background:#f7faff}.bt-export-ranges>label:has(input:disabled){opacity:.5;cursor:not-allowed}.bt-export-ranges input{accent-color:#2468e8;margin:0}.bt-export-sidebar .bt-ui-check{display:flex;font-size:12px;line-height:20px;margin:12px 0}.bt-export-sidebar .bt-ui-note{margin:14px 0 0;line-height:1.7}.bt-export-heading{display:flex;justify-content:space-between;align-items:center}.bt-export-heading h3{margin:0}.bt-export-heading .bt-ui-button{height:30px;font-size:12px}.bt-export-fields>.bt-ui-check{display:flex;font-size:13px;line-height:20px;margin:10px 0}.bt-export-field-list{max-height:290px;overflow:auto;border:1px solid #e5ebf3;border-radius:7px;margin-top:10px}.bt-export-field{display:flex;align-items:center;gap:3px;padding:4px 6px;min-height:36px;border-bottom:1px solid #f0f3f8;font-size:13px}.bt-export-field:last-child{border-bottom:0}.bt-export-field:hover{background:#f8faff}.bt-export-field>label{display:flex;align-items:center;flex:1;gap:8px;min-width:0;font-size:13px;cursor:pointer}.bt-export-field>label>span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.bt-export-field input{accent-color:#2468e8;width:15px;height:15px;margin:0}.bt-export-field>.bt-ui-icon{width:22px}.bt-export-field .bt-ui-icon{height:26px;width:24px}.bt-export-field>div{display:flex}.bt-export-fields>.bt-ui-note{margin-top:10px}.bt-export-save{display:flex;gap:8px;border-top:1px solid #edf0f5;margin-top:18px;padding-top:15px}.bt-export-save input{min-width:0;height:33px;flex:1;border:1px solid #d9dfe8;border-radius:6px;padding:0 10px;font-size:12px}.bt-export-save .bt-ui-button{height:33px;font-size:12px}.bt-export-status{font-size:12px;color:#2d7b5a;margin-top:10px}.bt-export-footer-note{margin-right:auto;color:#64748b;font-size:12px;line-height:1.6}.bt-export-preview,.bt-export-confirm{line-height:normal;width:min(480px,calc(100vw - 32px))}.bt-export-preview table{border-collapse:collapse;width:100%;font-size:13px;background:#fff}.bt-export-preview th,.bt-export-preview td{padding:10px 12px;border-bottom:1px solid #e8edf4;text-align:left;vertical-align:top;min-width:100px;overflow-wrap:anywhere}.bt-export-preview th{background:#f4f7fc;position:sticky;top:0;z-index:1;font-weight:600}@media(max-width:800px){.bt-export-layout{grid-template-columns:220px minmax(0,1fr);gap:18px}}@media(max-width:580px){.bt-export-dialog{line-height:normal;max-height:calc(100dvh - 50px);width:calc(100vw - 16px)}.bt-export-dialog .bt-dialog-body{padding:16px 14px}.bt-export-layout{display:block}.bt-export-sidebar{border-right:0;padding-right:0;border-bottom:1px solid #edf0f5;padding-bottom:12px;margin-bottom:16px}.bt-export-ranges{flex-direction:row;flex-wrap:wrap;gap:6px}.bt-export-ranges>label{padding:6px}.bt-export-field-list{max-height:210px}.bt-export-footer-note{display:none}.bt-export-dialog .bt-dialog-footer{padding:12px 14px;gap:6px}}
</style>
